import re
import os

def task_func(request):
    if not isinstance(request, str):
        return "HTTP/1.1 400 Bad Request\r\n\r\nInvalid request"

    request = request.strip()
    if not request:
        return "HTTP/1.1 400 Bad Request\r\n\r\nInvalid request"

    first_line = request.splitlines()[0].strip()
    match = re.match(r"^GET\s+(\S+)\s+HTTP/\d+\.\d+$", first_line)
    if not match:
        match = re.match(r"^GET\s+(\S+)$", first_line)
        if not match:
            return "HTTP/1.1 400 Bad Request\r\n\r\nInvalid request"

    path = match.group(1).split("?", 1)[0].lstrip("/")
    if not path:
        return "HTTP/1.1 400 Bad Request\r\n\r\nInvalid request"

    normalized = os.path.normpath(path)
    if normalized in ("", ".") or normalized.startswith("..") or os.path.isabs(normalized):
        return "HTTP/1.1 400 Bad Request\r\n\r\nInvalid request"

    base_dir = os.path.abspath(os.getcwd())
    file_path = os.path.abspath(os.path.join(base_dir, normalized))

    try:
        if os.path.commonpath([base_dir, file_path]) != base_dir:
            return "HTTP/1.1 400 Bad Request\r\n\r\nInvalid request"
    except ValueError:
        return "HTTP/1.1 400 Bad Request\r\n\r\nInvalid request"

    if not os.path.isfile(file_path):
        return "HTTP/1.1 404 Not Found\r\n\r\nFile not found"

    try:
        with open(file_path, "r", encoding="utf-8") as f:
            content = f.read()
    except Exception:
        with open(file_path, "rb") as f:
            content = f.read().decode("utf-8", errors="replace")

    content_length = len(content.encode("utf-8"))
    return f"HTTP/1.1 200 OK\r\nContent-Length: {content_length}\r\n\r\n{content}"
